import {Buffer, type Device} from '@luma.gl/core';
import {GPUVector, type GPUVectorFormat} from '@luma.gl/graph/gpu-data';
import {DataType, Float64, Vector} from 'apache-arrow';

/** Owned vectors produced from a numeric Arrow column. */
export type PreparedArrowColumnGPUVector = {
  /** Converted values, retaining the source chunk boundaries. */
  vector: GPUVector;
  /** Low Float32 components when precision preservation is requested or needed. */
  residualVector?: GPUVector;
  /** One uint32 validity value per logical row when nulls are preserved. */
  validityVector?: GPUVector;
  /** Converted vectors are owned by this result. */
  ownsVector: true;
  /** Destroys all buffers allocated for this result. */
  destroy(): void;
};

/** Options for conversion of fixed-width Arrow values for rendering. */
export type ArrowColumnGPUVectorOptions = {
  /** Name assigned to each output vector. */
  name?: string;
  /** Required float32 scalar/vector or normalized RGBA output format. */
  format: GPUVectorFormat;
  /** Convert RGB/RGBA inputs to normalized bytes, padding missing alpha. */
  color: boolean;
  /** Preserve null rows and return their validity instead of rejecting them. */
  preserveNulls: boolean;
  /** Generate residual-low values for precision-sensitive inputs. */
  fp64?: boolean;
  /** Transform each valid numeric row before packing its components. */
  transform?: (value: number[]) => readonly number[];
};

/** Options for selecting an output format from Arrow type metadata. */
export type ArrowColumnFormatOptions = Pick<
  Partial<ArrowColumnGPUVectorOptions>,
  'format' | 'transform'
> & {
  /** Selects numeric, XY/XYZ position, scalar, or normalized RGBA conversion. */
  semantic?: 'auto' | 'numeric' | 'position' | 'scalar' | 'color';
};

/**
 * Infers and validates a GPU format for an Arrow column without reading rows or uploading data.
 * Conversion still validates nulls and transformed row widths.
 */
export function getArrowConversionFormat(
  type: DataType,
  {semantic = 'auto', format, transform}: ArrowColumnFormatOptions = {}
): GPUVectorFormat {
  const listWidth = DataType.isFixedSizeList(type) ? type.listSize : undefined;
  if (semantic === 'position' && listWidth !== 2 && listWidth !== 3) {
    throw new Error('Arrow positions must be FixedSizeList[2] or FixedSizeList[3]');
  }
  if (semantic === 'scalar' && !DataType.isInt(type) && !DataType.isFloat(type)) {
    throw new Error('Arrow scalar input must be numeric');
  }
  const width = listWidth ?? 1;
  const outputFormat =
    format ??
    (semantic === 'color'
      ? 'unorm8x4'
      : width === 1
        ? 'float32'
        : (`float32x${width}` as GPUVectorFormat));
  validateArrowColumnFormat(
    type,
    outputFormat,
    semantic === 'color' || outputFormat === 'unorm8x4',
    transform
  );
  return outputFormat;
}

function validateArrowColumnFormat(
  sourceType: DataType,
  format: GPUVectorFormat,
  color: boolean,
  transform: ArrowColumnGPUVectorOptions['transform']
) {
  const width = format === 'float32' ? 1 : Number(/x([234])$/.exec(format)?.[1]);
  if (!width || (color ? format !== 'unorm8x4' : !format.startsWith('float32'))) {
    throw new Error(`Unsupported Arrow output format: ${format}`);
  }
  const list = DataType.isFixedSizeList(sourceType);
  const sourceWidth = list ? sourceType.listSize : 1;
  const type = list ? sourceType.children[0].type : sourceType;
  if (!DataType.isInt(type) && !DataType.isFloat(type)) {
    throw new Error('Arrow input must contain numeric values');
  }
  if ((!color && !transform && sourceWidth > width) || (color && ![3, 4].includes(sourceWidth))) {
    throw new Error('Arrow input width does not match the requested output format');
  }
  return {width, sourceWidth, type, list};
}

/** Converts fixed-width numeric Arrow chunks to owned GPU vectors with optional row transforms and validity. */
export function convertArrowColumnToGPUVector(
  device: Device,
  vector: Vector,
  options: ArrowColumnGPUVectorOptions
): PreparedArrowColumnGPUVector {
  const {name = 'arrow-column', format, color, preserveNulls} = options;
  const {width, sourceWidth, type, list} = validateArrowColumnFormat(
    vector.type,
    format,
    color,
    options.transform
  );
  const parts: GPUVector[] = [];
  const residuals: GPUVector[] = [];
  const validity: GPUVector[] = [];
  const owned: GPUVector[] = [];
  const upload = (
    values: Float32Array | Uint8Array | Uint32Array,
    rows: number,
    outputFormat: GPUVectorFormat
  ) => {
    // WebGPU copies require an aligned allocation, including odd-sized validity data.
    const bytes = new Uint8Array(Math.ceil(values.byteLength / 4) * 4);
    bytes.set(new Uint8Array(values.buffer, values.byteOffset, values.byteLength));
    const buffer = device.createBuffer({
      data: bytes,
      usage: Buffer.VERTEX | Buffer.COPY_SRC | Buffer.COPY_DST
    });
    try {
      const result = new GPUVector({
        type: 'buffer',
        name,
        buffer,
        ownsBuffer: true,
        format: outputFormat,
        length: rows
      });
      owned.push(result);
      return result;
    } catch (error) {
      buffer.destroy();
      throw error;
    }
  };
  try {
    for (const data of vector.data) {
      const chunk = new Vector([data]);
      const values =
        format === 'unorm8x4'
          ? new Uint8Array(chunk.length * width)
          : new Float32Array(chunk.length * width);
      const low =
        (options.fp64 || options.transform || type instanceof Float64) && !color
          ? new Float32Array(values.length)
          : undefined;
      const valid = preserveNulls ? new Uint32Array(chunk.length) : undefined;
      for (let row = 0; row < chunk.length; row++) {
        const value = chunk.get(row);
        const source = Array.from({length: sourceWidth}, (_, component) =>
          list ? value?.get(component) : value
        );
        let rowValid =
          value !== null &&
          source.every(component => component !== null && component !== undefined);
        const transformed =
          options.transform && rowValid ? options.transform(source.map(Number)) : source;
        if (transformed.length > width) {
          throw new Error('Arrow transformed width does not match the requested output format');
        }
        for (let component = 0; component < width; component++) {
          const input = component < transformed.length ? transformed[component] : color ? 255 : 0;
          rowValid &&= input !== null && input !== undefined;
          let number = Number(input ?? 0);
          // Floating point colors use [0, 1]; integer colors use [0, 255].
          if (color && DataType.isFloat(type) && component < transformed.length) number *= 255;
          const offset = row * width + component;
          values[offset] = color ? Math.round(Math.max(0, Math.min(255, number))) : number;
          if (low) low[offset] = number - values[offset];
        }
        if (!rowValid && !preserveNulls) throw new Error('Arrow column contains null rows');
        if (valid) valid[row] = Number(rowValid);
      }
      parts.push(upload(values, chunk.length, format));
      if (low) residuals.push(upload(low, chunk.length, format));
      if (valid) validity.push(upload(valid, chunk.length, 'uint32'));
    }
    const combine = (chunks: GPUVector[], outputFormat: GPUVectorFormat) =>
      new GPUVector({
        type: 'data',
        name,
        data: chunks.flatMap(chunk => chunk.data),
        format: outputFormat,
        ownsData: false
      });
    return {
      vector: combine(parts, format),
      residualVector: residuals.length ? combine(residuals, format) : undefined,
      validityVector: validity.length ? combine(validity, 'uint32') : undefined,
      ownsVector: true,
      destroy: () => {
        for (const chunk of owned.splice(0)) chunk.destroy();
      }
    };
  } catch (error) {
    for (const chunk of owned) chunk.destroy();
    throw error;
  }
}
